package main

import (
	"fmt"
	"os"
	"sort"
)

func main() {
	merged := load(os.Args[1:])
	keys := make([]string, 0, len(merged))
	for k := range merged {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	for _, k := range keys {
		fmt.Printf("%s=%s\n", k, merged[k])
	}
}

