"""Layered settings: files, environment, command line."""
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent / "config"
LOCKED = {"db.host"}
LAYERS = ["defaults", "site", "cli", "env", "environ"]  # lowest priority first


def read_ini(path):
    values = {}
    section = ""
    if not path.exists():
        return values
    for raw in path.read_text().splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        if line.startswith("["):
