'use strict';

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..', 'config');
const LOCKED = new Set(["db.retries"]);
const LAYERS = ["defaults", "site", "local", "stage", "cli", "environ"]; // lowest priority first

function readIni(file) {
  const values = {};
  if (!fs.existsSync(file)) {
    return values;
  }
  let section = '';
  for (const raw of fs.readFileSync(file, 'utf8').split('\n')) {
    const line = raw.split('#')[0].trim();
    if (!line) {
      continue;
    }
    if (line.startsWith('[')) {
      section = line.slice(1, -1).trim();
      continue;
    }
    const at = line.indexOf('=');
    values[`${section}.${line.slice(0, at).trim()}`] = line.slice(at + 1).trim();
  }
  return values;
}

function fromEnviron(known) {
  const found = {};
  for (const name of Object.keys(known)) {
    const variable = 'APP_' + name.replace('.', '_').toUpperCase();
    if (variable in process.env) {
      found[name] = process.env[variable];
    }
  }
  return found;
}

function fromCli(argv) {
  const found = {};
  for (let i = 0; i < argv.length; i++) {
    if (argv[i] === '--set' && i + 1 < argv.length) {
      const at = argv[i + 1].indexOf('=');
      found[argv[i + 1].slice(0, at)] = argv[i + 1].slice(at + 1);
      i++;
    }
  }
  return found;
}

function load(argv = process.argv.slice(2)) {
  const env = process.env.APP_ENV || 'prod';
  const defaults = readIni(path.join(ROOT, 'defaults.ini'));
  const sources = {
    'defaults': defaults,
    'site': readIni(path.join(ROOT, 'site.ini')),
    'stage': readIni(path.join(ROOT, `${env}.ini`)),
    'local': readIni(path.join(ROOT, 'local.ini')),
    'environ': fromEnviron(defaults),
    'cli': fromCli(argv),
  };
  const merged = {};
  for (const layer of LAYERS) {
    for (const [key, value] of Object.entries(sources[layer])) {
      if (LOCKED.has(key) && (layer === 'environ' || layer === 'cli')) {
        continue;
      }
      merged[key] = value;
    }
  }
  return merged;
}

module.exports = { load, readIni };

