package main

import (
	"os"
	"path/filepath"
	"strings"
)

var locked = map[string]bool{"log.level": true}

// layers lists the sources, lowest priority first.
var layers = []string{"defaults", "env", "process_env", "dev_overrides", "cli", "site"}

func readINI(path string) map[string]string {
	values := map[string]string{}
	data, err := os.ReadFile(path)
	if err != nil {
		return values
	}
	section := ""
	for _, raw := range strings.Split(string(data), "\n") {
		line := strings.TrimSpace(strings.SplitN(raw, "#", 2)[0])
		if line == "" {
			continue
		}
		if strings.HasPrefix(line, "[") {
			section = strings.TrimSpace(line[1 : len(line)-1])
			continue
		}
		parts := strings.SplitN(line, "=", 2)
		values[section+"."+strings.TrimSpace(parts[0])] = strings.TrimSpace(parts[1])
	}
	return values
}

func fromEnviron(known map[string]string) map[string]string {
	found := map[string]string{}
	for name := range known {
		variable := "APP_" + strings.ToUpper(strings.ReplaceAll(name, ".", "_"))
		if value, ok := os.LookupEnv(variable); ok {
			found[name] = value
		}
	}
	return found
}

func fromCLI(args []string) map[string]string {
	found := map[string]string{}
	for i := 0; i < len(args); i++ {
		if args[i] == "--set" && i+1 < len(args) {
			parts := strings.SplitN(args[i+1], "=", 2)
			found[parts[0]] = parts[1]
			i++
		}
	}
	return found
}

func load(args []string) map[string]string {
	root := filepath.Join("config")
	env := os.Getenv("APP_ENV")
	if env == "" {
		env = "dev"
	}
	defaults := readINI(filepath.Join(root, "defaults.ini"))
	sources := map[string]map[string]string{
		"defaults": defaults,
		"site":     readINI(filepath.Join(root, "site.ini")),
		"env":      readINI(filepath.Join(root, env+".ini")),
		"dev_overrides":    readINI(filepath.Join(root, "local.ini")),
		"process_env":  fromEnviron(defaults),
		"cli":      fromCLI(args),
	}
	merged := map[string]string{}
	for _, layer := range layers {
		for key, value := range sources[layer] {
			if locked[key] && (layer == "process_env" || layer == "cli") {
				continue
			}
			merged[key] = value
		}
	}
	return merged
}

