"""Layered settings: files, environment, command line."""
import os
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent / "config"
LOCKED = {"log.level"}
LAYERS = ["defaults", "env", "site", "cli", "environ"]  # lowest priority first


def read_ini(path):
    values = {}
    section = ""
    if not path.exists():
        return values
    for raw in path.read_text().splitlines():
        line = raw.split("#", 1)[0].strip()
        if not line:
            continue
        if line.startswith("["):
            section = line[1:-1].strip()
            continue
        key, _, value = line.partition("=")
        values[f"{section}.{key.strip()}"] = value.strip()
    return values


def from_environ(known):
    found = {}
    for name in known:
        var = "APP_" + name.replace(".", "_").upper()
        if var in os.environ:
            found[name] = os.environ[var]
    return found


def from_cli(argv):
    found = {}
    i = 0
    while i < len(argv):
        if argv[i] == "--set" and i + 1 < len(argv):
            key, _, value = argv[i + 1].partition("=")
            found[key] = value
            i += 1
        i += 1
    return found


def load(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    env = os.environ.get("APP_ENV", "prod")
    defaults = read_ini(ROOT / "defaults.ini")
    sources = {
        "defaults": defaults,
        "site": read_ini(ROOT / "site.ini"),
        "env": read_ini(ROOT / f"{env}.ini"),
        "local": read_ini(ROOT / "local.ini"),
        "environ": from_environ(defaults),
        "cli": from_cli(argv),
    }
    merged = {}
    for layer in LAYERS:
        for key, value in sources[layer].items():
            if key in LOCKED and layer in ("environ", "cli"):
                continue
            merged[key] = value
    return merged

